function IdolLive3D_UIStageJumpBtn_Pos:__init( btnTF_, parentEnv_ )

    self.ImgBgUnlock = btnTF_:Find("Root/ImgBgUnlock")
    self.ImgBgLock   = btnTF_:Find("Root/ImgBgLock")
    self.ImgIcon1 = self.ImgBgUnlock:Find("ImgIcon1") -- 猫图状态

    self.super.__init( self, btnTF_, Live3D_UIKey.stageJumpBtn_pos, parentEnv_, 
        -- setShowCB_:
        function( isShow_ )
            CfUtils.SetActive( self.btnTF, isShow_==true )
        end, 
        -- setGrayCB_:
        function( isGray_ )
            CfUtils.SetActive( self.ImgBgUnlock, not isGray_ )
            CfUtils.SetActive( self.ImgBgLock, isGray_ )
        end, 
        -- btnClickCB_:
        function()
            Events.Broadcast(IdolLive3D_States.EventStageJumpByKey, self.uiKey)
        end
    )

    ---
    if self.events_2 then
        CfUtils.EventsUndecorated(self.events_2)
    end
    self.events_2 = CfUtils.EventsDecorated({
        [IdolLive3D_States.EventChangeUIPosStageJumpBtnImg] = function( imgIdx_ )
            assert( isNotNull(self.ImgIcon1) )
            assert( type(imgIdx_) == "number" )
            CfUtils.SetUISwitchImage( self.ImgIcon1, imgIdx_ )
        end,

    })
end


-- 需手动调用 Delete()
function IdolLive3D_UIStageJumpBtn_Pos:__delete()
    if self.events_2 then
        CfUtils.EventsUndecorated(self.events_2)
    end
    self.super.__delete(self)
end



